package com.andrey.litrpg.boss;

import java.util.Map;

/**
 * Слова хранителей (при вступлении в бой) и краткая тактика для Кодекса. Общее для сервера и клиента.
 */
public final class BossGuide {
    public record Entry(String quote, String tactic) {
    }

    private static final Map<String, Entry> ALL = Map.ofEntries(
            Map.entry("trial_warden", new Entry("Покажите, чему научились.",
                    "Пробный хранитель полигона: конус по танку, кольцо (вплотную безопасно), метеоры под каждым, ноша на разделение, сбить «Восстановление».")),
            Map.entry("gatekeeper", new Entry("Живым — не сюда.",
                    "Танк держит Привратника спиной к отряду: цепь бьёт конусом. «Костяной вал» — встать вплотную. Крыс — по площади. «Костяной щит» — сбить оглушением. «Костяной залп» — круг под вами: шаг в сторону или за колонну. «Цепная хватка» летит к дальнему — уйдите с полосы, иначе притянет. С половины цепь бьёт дважды, а «Цепи из стен» бьют поперёк арены по очереди. «Костяной частокол» делит арену грядами — не стойте на них; с половины «Склеп оживает» — круги трухи на полу.")),
            Map.entry("morra", new Entry("Сестра, у нас гости.",
                    "Две сестры: пала одна — вторая поднимет её через 12 с. Сводите здоровье вровень и добивайте обеих. Луч между ними режет урон вдвое — кто-то крепкий встаёт в луч и рвёт связь. «Тёмное лечение» Вессы — сбить, «Проклятие» — лечить. «Рой душ» Морры плывёт к Вессе — перехватите души, встав на пути. «Тёмные свечи» Вессы бьют тенью — разбейте их. Морра: «Поле жатвы» — горят две четверти, потом две другие; «След косы» — водите её по краю; «Сестринская черта» горит между сёстрами — не стойте между ними. Весса: «Порченая земля» под каждым, «Тёмный круг» в середине, «Ползучая тень» гонится за бойцом.")),
            Map.entry("vessa", new Entry("Морра, не спеши.", "Младшая из сестёр — лечит, проклинает, бьёт волной вокруг себя.")),
            Map.entry("lich", new Entry("Свет здесь — гость. А гостей я не держу.",
                    "Ледяные гробницы — разбить быстро. Поднятых стражей — танку. На половине — Тронный зал: когда гаснет свет, стойте у душевных жаровен. На четверти — разбить филактерию, пока лич под щитом. «Ледяная тропа» — уйдите с дорожки. «Зов вьюги» в Тронном зале — не стойте: кто стоит, тот замерзает. «Ледяное поле» замораживает край зала — к центру. В Тронном зале «Ледяные стены» — коридор между двумя грядами.")),
            Map.entry("arachna", new Entry("Ещё мясо в сеть.",
                    "Яйца — разбить до вылупления. Коконы — разрезать, внутри союзник травится. Паутина приковывает — уходите с полос. Когда Аракна под сводами — разбегитесь от ядовитого дождя и уйдите из круга её падения. «Прыжок охотницы» — на дальнего: уйдите из круга, после — лужи яда. С 66% «Ядовитый веер» — три струи по очереди: слева, справа, по центру. «Ядовитые лужи» под тремя бойцами стоят долго — не бейтесь в них. С 66% половину логова затягивает «Сеть на полу».")),
            Map.entry("rot_ent", new Entry("Всё растёт вниз. И вы тоже.",
                    "Уводите Древня от споровых облаков — они растут. Корни приковывают — не стойте на полосах. «Сердцевину» — сбить. С половины — стражи леса и споры вдвое чаще. «Гнилые плоды» — разбейте до того, как лопнут в споры. С половины «Хватка корней» тянет к Древню — уходите из круга против тяги. «Корневая решётка» — стойте в клетках «#», не на корнях. С половины «Споровый след» — водите Древня по краю.")),
            Map.entry("morena", new Entry("Чего ты боишься?",
                    "Напуганного не оставлять одного: подойдите — страх спадёт. Котлы замедляют — обходите. Отражения лечат ведьму — убить. В Изнанке: кольцо, круг, кольцо — к ней, от неё, к ней. «Сглаз» — меченому не смотреть на Морену, иначе страх. С 75% «Хоровод теней»: огни кружат вокруг ведьмы — шагайте в просветы. «Круг ведьмы» — выведите Морену из круга. С 75% «Изнаночные клетки» — пол-шахматка, горят то одни клетки, то другие.")),
            Map.entry("tide_warden", new Entry("Прилив не спрашивает.",
                    "Перед «Волной» встаньте за колонну — между вами и стороной, откуда идёт вода. Водоворот в центре тянет — держитесь края. С половины волны чаще и бывают отбойные. «Брызги прибоя» — три веера по очереди. С половины «Отбойный удар» отбрасывает к краю — держитесь подальше. Главное — прилив и отлив: в прилив Страж бьёт без остановки и почти неуязвим — уходите из-под ударов; в отлив он выдыхается («Отлив — бейте!», урон ×2,5) — тогда всё в него. «Течения» сносят вбок, «Пена» вязкая.")),
            Map.entry("leviathan", new Entry("…",
                    "Нырок: Левиафан вынырнет в круге под одним из вас — уйдите. Хвост бьёт кольцом — ближе к голове безопасно. Прилив заливает половину арены — на сухую сторону. «Водяной смерч» бродит по арене и затягивает — обходите. С 66% «Рёв глубин» — отойдите от головы, иначе немота. «Чернильное пятно» ползёт за дальним — уводи. С 66% «Отбойное течение» несёт половину зала к краю.")),
            Map.entry("naiad", new Entry("Пойте со мной.",
                    "«Сияние глубин»: бейте только из пятен света. «Песнь глубин» — сбить, иначе удар по всем. Копья летят к каждому — разбегитесь. На половине — Святилище на дне. «Спиральные копья» — две волны по восемь, встаньте в просвет. С 66% «Слёзы глубин» — встаньте на каждую слезу, иначе жрица лечится. «Жемчужные кольца» — ближнее, дальнее, снова ближнее: шагайте между ними. С 66% «Святые воды» — уведите Наяру от источника, там она лечится.")),
            Map.entry("smelter", new Entry("ПЕРЕПЛАВИТЬ.",
                    "Рядом с големом копится жар: полная шкала — расплав по вам и соседям. Сбросить — встать в чан с водой. Полосы расплава оставляют огонь. Броня — разбить заклёпки по краю. «Наковальни» шагают к дальнему — уходите вбок. С 66% «Раскалённый слиток» — передайте его, подойдя вплотную к союзнику; три передачи — и он остынет. «Разлив металла» режет зал полосами на 10 с. С 66% «Горячий пол» — два сектора, потом поворот на четверть.")),
            Map.entry("chariot", new Entry("Круг первый!",
                    "Уходите с полосы разгона — после неё горит след. Каждый круг быстрее. После четвёртого — пит-стоп: колесница уязвима, бейте всем. «Пламенный выхлоп» бьёт за колесницей — не стойте сзади. Со второго круга «Призрачный обгон» — встаньте в просвет между полосами. «Огненная колея» — две полосы огня поперёк. Со второго круга «Гоночный круг» — край в огне, бой в середине.")),
            Map.entry("ash_lord", new Entry("Покажи, чего ты стоишь. Один.",
                    "«Эго»: лучший боец дерётся с Владыкой один — остальным не мешать, лекарю держать дуэлянта. Обвалы оставляют лаву. На половине — Кальдера: извержение под каждым. «Клеймо пепла» — меченый уводит горящий след вдоль края. «Пепельная корона» — глыбы падают по кругу, идите за ними. «Пепельное облако» ползёт за дальним. В Кальдере «Озёра лавы» отнимают место — держите бой подальше от них.")),
            Map.entry("doppel", new Entry("Твой следующий соперник — ты.",
                    "У каждого — своя тень: бейте свою, чужие почти неуязвимы. Пока тени живы, Двойник почти неуязвим. «Зеркало» — прекратите бить. «Обмен» меняет двоих местами. «Осколки зеркала» сыплются по очереди — смотрите под ноги. С 80% «Зеркальный веер» бьёт вперёд и назад — стойте сбоку. «Зеркальные лужи» — под вами и в отражении через центр. С 80% «Зеркальный коридор» — все в коридор, вокруг горит.")),
            Map.entry("chronophage", new Entry("У вас нет времени.",
                    "Песочные часы — разбить до срока, иначе время остановится. «Откат» вернёт всех на метки — сразу сходите с них. С половины всё быстрее. «Эхо удара» повторяет круг на том же месте — ушли, не возвращайтесь. С половины «Застывшее время» — не стойте в пятнах. «Часовая стрелка» идёт по кругу — уходите из-под неё. С половины «Застывшие следы»: где вы стояли 2 с назад — зона; не возвращайтесь.")),
            Map.entry("xalathar", new Entry("Я хочу. Я хочу. Я ХОЧУ.",
                    "«Голод» съедает самого раненого — держите всех полными. Край рушится — к центру, там остаётся пустота. На половине — Сердце Бездны. На четверти — «Конец всего»: волны по всем, всё сильнее; добивайте быстро. «Пасть бездны» втягивает в последний миг — бегите раньше. С 75% «Тысяча глаз» — разбейте глаза, лучи видны заранее. «Разрывы пустоты» — хорды через арену, обходите. С 75% «Тьма сгущается» — свет только у Ксалатара, все к нему.")));

    private BossGuide() {
    }

    public static Entry of(String id) {
        return ALL.getOrDefault(id, new Entry("", ""));
    }

    /** Давление хранителя (фаза 12): как зовутся его волна по отряду и метка на бойце, цвет. */
    public record Pressure(String pulse, String mark, int color) {
    }

    private static final Map<String, Pressure> PRESSURE = Map.ofEntries(
            Map.entry("trial_warden", new Pressure("Давление Системы", "Метка Системы", 0x7FB8FF)),
            Map.entry("gatekeeper", new Pressure("Гул врат", "Костяная заноза", 0xE8E0C8)),
            Map.entry("morra", new Pressure("Шёпот сестёр", "Метка жатвы", 0x9B5CFF)),
            Map.entry("lich", new Pressure("Дыхание склепа", "Метка холода", 0x8FE3FF)),
            Map.entry("arachna", new Pressure("Ядовитые испарения", "Укус паучонка", 0x8FD14F)),
            Map.entry("rot_ent", new Pressure("Гнилой ветер", "Спора в крови", 0x9BB84A)),
            Map.entry("morena", new Pressure("Шёпот страха", "Порча", 0xB04AD8)),
            Map.entry("tide_warden", new Pressure("Холод прилива", "Метка глубины", 0x4AA8E8)),
            Map.entry("leviathan", new Pressure("Давление глубин", "Солёная рана", 0x2A7AB8)),
            Map.entry("naiad", new Pressure("Песнь в воде", "Метка сирены", 0x7FE8E0)),
            Map.entry("smelter", new Pressure("Жар горна", "Окалина", 0xFF8A2E)),
            Map.entry("chariot", new Pressure("Раскалённый ветер", "Метка колеи", 0xFFB04A)),
            Map.entry("ash_lord", new Pressure("Пепельный дождь", "Тлеющее клеймо", 0xD8542A)),
            Map.entry("doppel", new Pressure("Отражение боли", "Метка двойника", 0xC8C8E0)),
            Map.entry("chronophage", new Pressure("Тиканье", "Метка времени", 0xFFE27A)),
            Map.entry("xalathar", new Pressure("Шёпот Бездны", "Метка пустоты", 0x6A2AB8)));

    /** Давление хранителя или null (вторая сестра молчит — давит первая). */
    public static Pressure pressure(String id) {
        return PRESSURE.get(id);
    }
}
